     let currentPage = 1;
     let resultsPerPage = 10;
     let allTerms = [];

     // Fetch all terms for suggestions (on page load, no results shown)
     async function fetchAllTermsForSuggestions() {
       try {
         const resp = await fetch('https://mil.psy.ntu.edu.tw:5000/terms');
         if (!resp.ok) return;
         const ct = resp.headers.get('content-type') || '';
         if (ct.includes('application/json')) {
           const data = await resp.json();
           if (Array.isArray(data)) {
             allTerms = data;
           } else if (data && Array.isArray(data.terms)) {
             allTerms = data.terms;
           } else {
             allTerms = [];
           }
         }
       } catch (err) {
         // Silently fail, suggestions will just not appear
       }
     }

     // Fetch all terms for results (button click)
     async function fetchTerms() {
       document.getElementById('table-container').innerHTML = '';
       document.getElementById('table-pagination').innerHTML = '';
       document.getElementById('table-controls').innerHTML = '';
       document.getElementById('total-results').innerHTML = '';
       let out = document.getElementById('out');
       if (out) out.textContent = 'Requesting…';
       try {
         const resp = await fetch(`https://mil.psy.ntu.edu.tw:5000/terms?page=${currentPage}&per_page=${resultsPerPage}`);
         let info = `HTTP ${resp.status} ${resp.statusText}\n`;
         const ct = resp.headers.get('content-type') || '';

         if (!resp.ok) {
           const text = await resp.text();
           if (out) out.textContent = info + '\n' + text;
           return;
         }

         if (ct.includes('application/json')) {
           const data = await resp.json();
           let terms = [];
           if (Array.isArray(data)) {
             terms = data;
           } else if (data && Array.isArray(data.terms)) {
             terms = data.terms;
           }
           tableData = terms.map(t => ({ term: t }));
           tableColumns = [ { key: 'term', label: 'Term' } ];
           tablePage = 1;
           tableResultsPerPage = 10;
           renderTable();
           if (out) out.textContent = '';
         } else {
           const text = await resp.text();
           if (out) out.textContent = info + '\n' + text;
         }
       } catch (err) {
         if (out) out.textContent = 'Error: ' + (err && err.message ? err.message : String(err));
       }
     }
@@ async function fetchTermDetails() {
         const term = document.getElementById('term-input').value.trim();
         const out = document.getElementById('out');
