// Debounce utility
function debounce(fn, delay) {
  let timer = null;
  return function(...args) {
    clearTimeout(timer);
    timer = setTimeout(() => fn.apply(this, args), delay);
  };
}

// Real-time AJAX for term details
const termInput = document.getElementById('term-input');
if (termInput) {
  termInput.addEventListener('input', debounce(function() {
    const value = termInput.value.trim();
    if (value) {
      fetchTermDetails();
    }
  }, 400));
}

// Real-time AJAX for multi-term study search
for (let i = 0; i < 5; i++) {
  const input = document.getElementById(`study-term-${i}`);
  if (input) {
    input.addEventListener('input', debounce(function() {
      // Only trigger if at least one term is entered
      const query = buildMultiTermQuery();
      if (query) {
        fetchMultiQueryStudies();
      }
    }, 400));
  }
}
// ...existing code...
"}

