let sortKey = null;
let sortOrder = 'desc'; // 'asc' or 'desc'

function renderTable() {
  // ...existing code...
  // Show alphabet filter only for Fetch All Terms (when tableColumns is just 'Term')
  if (tableColumns.length === 1 && tableColumns[0].key === 'term') {
    alphabetDiv.style.display = '';
    renderAlphabetFilter();
  } else {
    alphabetDiv.style.display = 'none';
  }
  container.innerHTML = '';
  pagination.innerHTML = '';
  // controls.innerHTML = '';
  // Filter tableData by alphabet if set
  let filteredData = tableData;
  if (alphabetFilter) {
    filteredData = tableData.filter(row => row.term && row.term[0] && row.term[0].toUpperCase() === alphabetFilter);
  }
  // Sort if sortKey is set and tableColumns match associated terms
  if (tableColumns.length === 2 && (sortKey === 'co_count' || sortKey === 'term')) {
    filteredData = filteredData.slice().sort((a, b) => {
      if (sortKey === 'co_count') {
        return sortOrder === 'asc' ? a.co_count - b.co_count : b.co_count - a.co_count;
      } else if (sortKey === 'term') {
        if (a.term < b.term) return sortOrder === 'asc' ? -1 : 1;
        if (a.term > b.term) return sortOrder === 'asc' ? 1 : -1;
        return 0;
      }
      return 0;
    });
  }
  totalDiv.textContent = `Total results: ${filteredData.length}`;
  if (!filteredData || filteredData.length === 0) {
    container.innerHTML = '<div class="text-gray-500">No results to display.</div>';
    return;
  }
  const start = (tablePage - 1) * tableResultsPerPage;
  const end = Math.min(start + tableResultsPerPage, filteredData.length);
  const pageResults = filteredData.slice(start, end);
  let table = '<table class="min-w-full text-sm text-left border"><thead><tr>';
  for (const col of tableColumns) {
    let sortIcon = '';
    if (tableColumns.length === 2 && (col.key === 'co_count' || col.key === 'term')) {
      if (sortKey === col.key) {
        sortIcon = sortOrder === 'asc' ? ' ▲' : ' ▼';
      }
      table += `<th class="border px-2 py-1 cursor-pointer select-none" onclick="window.sortTableBy('${col.key}')">${col.label}${sortIcon}</th>`;
    } else {
      table += `<th class="border px-2 py-1">${col.label}</th>`;
    }
  }
  table += '</tr></thead><tbody>';
  for (const row of pageResults) {
    table += '<tr>';
    for (const col of tableColumns) {
      table += `<td class="border px-2 py-1">${row[col.key] || ''}</td>`;
    }
    table += '</tr>';
  }
  table += '</tbody></table>';
  container.innerHTML = table;
  // ...existing code...
}

// Sorting handler (global for inline onclick)
window.sortTableBy = function(key) {
  if (sortKey === key) {
    sortOrder = sortOrder === 'asc' ? 'desc' : 'asc';
  } else {
    sortKey = key;
    sortOrder = key === 'co_count' ? 'desc' : 'asc';
  }
  tablePage = 1;
  renderTable();
};
// ...existing code...
"}

