      } else {
        const aVal = (a[studySortKey] || '').toString().toLowerCase();
        const bVal = (b[studySortKey] || '').toString().toLowerCase();
        if (aVal < bVal) return studySortOrder === 'asc' ? -1 : 1;
        if (aVal > bVal) return studySortOrder === 'asc' ? 1 : -1;
        return 0;
      }
    });
  }

  const start = (studyResultsPage - 1) * studyResultsPerPage;
  const end = Math.min(start + studyResultsPerPage, sortedResults.length);
  const pageResults = sortedResults.slice(start, end);
